// Claude's review tests for A18 (keyboard, names, focus, and the polish notes). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type SocketMock, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method: 'GET',
    urlPattern,
    response: { status: 200, headers: { 'content-type': 'application/json' }, body: '{"a":1}', bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

const hub: SocketMock = {
  id: 's1', name: 'Hub', enabled: true, kind: 'signalr', urlPattern: '/hubs/x',
  onConnect: [{ id: 'p1', afterMs: 0, target: 'Receive', data: '["a"]' }],
  replies: [{ id: 'r1', when: 'Send', respond: 'fixed', result: '', pushes: [] }],
  createdAt: 0,
};

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'default',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('one', '/api/one'), mock('two', '/api/two', { match: { query: { a: '1' } } })], sockets: [hub] },
      { id: 'b', name: 'Other', mocks: [mock('three', '/api/three')] },
    ],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(p: Project | null = project()): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: p ? [p] : [] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

/** Every visible button's accessible name: aria-label, else aria-labelledby text, else its text. Title does not count. */
function unnamedButtons(panel: Page) {
  return panel.evaluate(() => {
    const out: string[] = [];
    for (const b of Array.from(document.querySelectorAll('button'))) {
      const r = b.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) continue;
      const label = b.getAttribute('aria-label')?.trim()
        || (b.getAttribute('aria-labelledby') ? document.getElementById(b.getAttribute('aria-labelledby')!)?.textContent?.trim() : '')
        || (b.textContent ?? '').trim();
      // A lone symbol is not a name.
      if (!label || /^[←-⇿⌀-⏿■-◿✀-➿×✕✖+\-–—…·]+$/u.test(label)) {
        out.push(b.outerHTML.slice(0, 120));
      }
    }
    return out;
  });
}

test('every visible button has a real name, on both tabs and in both editors', async () => {
  const { page, panel } = await open();
  try {
    await page.evaluate(async () => (await fetch('/api/one')).text());
    await panel.getByTestId('log-row').first().click();
    expect(await unnamedButtons(panel)).toEqual([]);

    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'two' }).click();
    await expect(panel.getByTestId('match-section')).toBeVisible();
    expect(await unnamedButtons(panel)).toEqual([]);

    await panel.getByTestId('socket-row').first().click();
    await expect(panel.getByTestId('socket-name')).toBeVisible();
    expect(await unnamedButtons(panel)).toEqual([]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the main path works by keyboard: a log row, Mock this, edit, Save', async () => {
  const { page, panel } = await open({ ...project(), scenarios: [{ id: 'default', name: 'Default', mocks: [] }] });
  try {
    await page.evaluate(async () => (await fetch('/api/goals')).text());
    const row = panel.getByTestId('log-row').filter({ hasText: '/api/goals' }).first();
    await expect(row).toBeVisible();
    await row.focus();
    await expect(row).toBeFocused();
    await panel.keyboard.press('Enter');
    await expect(panel.getByTestId('detail-url')).toContainText('/api/goals');

    await panel.getByTestId('mock-this').focus();
    await panel.keyboard.press('Enter');
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks.length).toBe(1);

    // Mock this stays on the Log, as with the mouse; go to the mock by keyboard.
    await panel.getByTestId('tab-mocks').focus();
    await panel.keyboard.press('Enter');
    const mrow = panel.getByTestId('mock-row').first();
    await mrow.focus();
    await panel.keyboard.press('Enter');
    await expect(panel.getByTestId('field-pattern')).toHaveValue('/api/goals');

    await panel.getByTestId('field-status').focus();
    await panel.keyboard.press('Control+A');
    await panel.keyboard.type('418');
    await panel.getByTestId('mock-save').focus();
    await panel.keyboard.press('Enter');
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[0]?.response.status).toBe(418);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('mock rows, socket rows and scenario headers open with Enter and Space', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    const two = panel.getByTestId('mock-row').filter({ hasText: 'two' });
    await two.focus();
    await expect(two).toBeFocused();
    await panel.keyboard.press('Enter');
    await expect(panel.getByTestId('field-name')).toHaveValue('two');

    const sock = panel.getByTestId('socket-row').first();
    await sock.focus();
    await panel.keyboard.press(' ');
    await expect(panel.getByTestId('socket-name')).toHaveValue('Hub');

    const header = panel.locator('.scenario-group').filter({ hasText: 'Other' }).locator('.scenario-group-header');
    await header.focus();
    await expect(header).toBeFocused();
    await panel.keyboard.press('Enter');
    await expect(panel.locator('.scenario-group').filter({ hasText: 'Other' })).toHaveClass(/selected/);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Tab moves through the top bar in order and shows a focus ring', async () => {
  const { page, panel } = await open();
  try {
    await panel.locator('body').click({ position: { x: 1, y: 1 } });
    const seen: string[] = [];
    for (let i = 0; i < 12; i++) {
      await panel.keyboard.press('Tab');
      const info = await panel.evaluate(() => {
        const el = document.activeElement as HTMLElement | null;
        if (!el || el === document.body) return null;
        const cs = getComputedStyle(el);
        const ring = (cs.outlineStyle !== 'none' && parseFloat(cs.outlineWidth) > 0) || (cs.boxShadow && cs.boxShadow !== 'none');
        return { id: el.getAttribute('data-testid') ?? el.tagName, ring };
      });
      if (!info) continue;
      seen.push(info.id);
      expect(info.ring, `focus ring on ${info.id}`).toBeTruthy();
    }
    for (const id of ['project-picker', 'rec-toggle', 'console-toggle', 'power-toggle', 'tab-log', 'tab-mocks']) {
      expect(seen, `${id} reached by Tab`).toContain(id);
    }
    expect(seen.indexOf('project-picker')).toBeLessThan(seen.indexOf('power-toggle'));
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Test bar keeps request headers folded until asked', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await expect(panel.getByTestId('test-req-headers')).toHaveCount(0);
    await panel.getByTestId('test-headers-toggle').click();
    await expect(panel.getByTestId('test-req-headers')).toBeVisible();
    await panel.getByTestId('test-req-headers').fill('x-a: 1');
    await panel.getByTestId('test-headers-toggle').click();
    // Folding keeps what was typed, and the toggle says so.
    await expect(panel.getByTestId('test-req-headers')).toHaveCount(0);
    await expect(panel.getByTestId('test-headers-toggle')).toContainText('1');
    await panel.getByTestId('test-headers-toggle').click();
    await expect(panel.getByTestId('test-req-headers')).toHaveValue('x-a: 1');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Match only when: request headers are named apart, and the body help shows once', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'two' }).click();
    const section = panel.getByTestId('match-section');
    await expect(section).toContainText('Request headers');
    const help = 'these fields must be in the body';
    const placeholder = await panel.getByTestId('match-body').getAttribute('placeholder');
    const shown = (await section.innerText()).split(help).length - 1;
    expect(shown + (placeholder?.includes(help) ? 1 : 0)).toBe(1);
    // The add buttons look like the editor's other "+ Add" links: no border.
    for (const id of ['match-query-add', 'match-header-add']) {
      const width = await panel.getByTestId(id).evaluate((el) => getComputedStyle(el).borderTopWidth);
      expect(parseFloat(width), id).toBe(0);
    }
  } finally {
    await panel.close();
    await page.close();
  }
});
